// CreateCopilotMessage is the resolver for the createCopilotMessage field.
func (r *mutationResolver) CreateCopilotMessage(ctx context.Context, options model.CreateChatMessageInput) (string, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return "", ErrAuthenticationRequired
	}
	if r.CopilotSessions == nil {
		return "", ErrCopilotSessionsUnavailable
	}
	workspaceID, docID, err := r.CopilotSessions.GetScope(ctx, principal.User.ID, options.SessionID)
	if err != nil {
		return "", err
	}
	action := "Workspace.Copilot"
	if docID != nil && *docID != "" {
		action = "Doc.Update"
	}
	_, personal, err := r.authorizeCopilotScope(ctx, workspaceID, docID, action)
	if err != nil {
		return "", err
	}
	if personal && (options.Blob != nil || len(options.Blobs) > 0 || len(options.Attachments) > 0) {
		return "", errors.New("Local workspaces don't support attachments or references.")
	}
	if options.Params != nil {
		if copilotParamsRequireWorkspace(options.Params.Value) {
			return "", errors.New("Copilot workspace references are not supported yet")
		}
	}
	var params json.RawMessage
	if options.Params != nil {
		params, err = json.Marshal(options.Params.Value)
		if err != nil {
			return "", err
		}
	}
	attachments := make([]string, 0, len(options.Attachments)+len(options.Blobs)+1)
	attachments = append(attachments, options.Attachments...)
	artifactAttachments := make([]copilot.MessageArtifactAttachment, 0, len(options.Blobs)+1)
	uploads := make([]*graphql.Upload, 0, len(options.Blobs)+1)
	if options.Blob != nil {
		uploads = append(uploads, options.Blob)
	}
	uploads = append(uploads, options.Blobs...)
	if len(attachments)+len(uploads) > 10 {
		return "", errors.New("Copilot messages support at most 10 attachments")
	}
	if len(uploads) > 0 && r.CopilotAttachments == nil {
		return "", errors.New("Copilot attachments are unavailable")
	}
	for _, upload := range uploads {
		if upload == nil || upload.File == nil {
			return "", errors.New("Copilot attachment body is required")
		}
		attachmentURL, artifact, uploadErr := r.CopilotAttachments.UploadForMessage(ctx, principal.User.ID, options.SessionID, upload.Filename, upload.ContentType, upload.File)
		if uploadErr != nil {
			return "", uploadErr
		}
		attachments = append(attachments, attachmentURL)
		artifactAttachments = append(artifactAttachments, artifact)
	}
	messageID, err := r.CopilotSessions.CreateUserMessage(ctx, copilot.CreateUserMessageInput{
		UserID: principal.User.ID, SessionID: options.SessionID, Content: options.Content,
		Attachments: attachments, ArtifactAttachments: artifactAttachments, Params: params,
	})
	return messageID, err
}

