// ImportUsers is the resolver for the importUsers field.
func (r *mutationResolver) ImportUsers(ctx context.Context, input model.ImportUsersInput) ([]model.UserImportResultType, error) {
	if err := requireAdministrator(ctx); err != nil {
		return nil, err
	}
	if r.UserManagement == nil {
		return nil, users.ErrUserManagementUnavailable
	}
	results := make([]model.UserImportResultType, len(input.Users))
	type importJob struct {
		index int
		user  *model.CreateUserInput
	}
	jobs := make(chan importJob)
	workerCount := min(8, len(input.Users))
	var workers sync.WaitGroup
	for range workerCount {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for job := range jobs {
				if err := ctx.Err(); err != nil {
					results[job.index] = model.UserImportFailedType{Email: job.user.Email, Error: err.Error()}
					continue
				}
				user, err := r.UserManagement.CreateAdminUser(ctx, users.CreateInput{
					Email: job.user.Email, Name: job.user.Name, Password: job.user.Password,
				})
				if err != nil {
					message := err.Error()
					if errors.Is(err, users.ErrEmailAlreadyUsed) {
						message = "This email has already been registered."
					}
					results[job.index] = model.UserImportFailedType{Email: job.user.Email, Error: message}
					continue
				}
				results[job.index] = userModel(user)
			}
		}()
	}
	for index, inputUser := range input.Users {
		if inputUser == nil {
			results[index] = model.UserImportFailedType{Error: "invalid user input"}
			continue
		}
		select {
		case jobs <- importJob{index: index, user: inputUser}:
		case <-ctx.Done():
			results[index] = model.UserImportFailedType{Email: inputUser.Email, Error: ctx.Err().Error()}
		}
	}
	close(jobs)
	workers.Wait()
	return results, nil
}

