// GrantMember is the resolver for the grantMember field.
func (r *mutationResolver) GrantMember(ctx context.Context, permission model.Permission, userID string, workspaceID string) (bool, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return false, ErrAuthenticationRequired
	}
	if r.WorkspaceRoles.Repository == nil {
		return false, ErrWorkspaceRoleMutationUnavailable
	}
	role, ok := mapPermissionToWorkspaceRole(permission)
	if !ok {
		return false, ErrWorkspaceRoleMutationUnavailable
	}
	transition, err := r.WorkspaceRoles.Repository.TransitionWorkspaceRole(ctx, principal.User.ID, workspaceID, userID, role)
	if err != nil {
		return false, workspaceRoleMutationResolverError(err, workspaceID)
	}
	if role == "external" {
		if err := r.publishWorkspaceMemberRemovalEffects(ctx, principal.User.ID, userID, workspaceID, transition); err != nil {
			return false, err
		}
	}
	if r.WorkspaceRoles.Publisher != nil {
		r.WorkspaceRoles.Publisher.PublishWorkspaceMembersUpdated(workspaceID)
	}
	return true, nil
}

