// LeaveWorkspace is the resolver for the leaveWorkspace field.
func (r *mutationResolver) LeaveWorkspace(ctx context.Context, sendLeaveMail *bool, workspaceID string, workspaceName *string) (bool, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return false, ErrAuthenticationRequired
	}
	if r.WorkspaceRoles.Repository == nil {
		return false, ErrWorkspaceRoleMutationUnavailable
	}
	if err := r.WorkspaceRoles.Repository.LeaveWorkspace(ctx, principal.User.ID, workspaceID); err != nil {
		switch {
		case errors.Is(err, workspaces.ErrWorkspaceOwnerCannotLeave):
			return false, err
		case errors.Is(err, workspaces.ErrWorkspaceMemberNotFound), errors.Is(err, workspaces.ErrNotFound):
			return false, &WorkspaceRoleMutationError{Cause: err, WorkspaceID: workspaceID}
		case errors.Is(err, workspaces.ErrAccessDenied):
			return false, &WorkspaceRoleMutationError{Cause: workspaces.ErrWorkspaceRolePermissionDenied, WorkspaceID: workspaceID}
		default:
			return false, err
		}
	}
	if r.WorkspaceRoles.LeaveMailer != nil {
		if err := r.WorkspaceRoles.LeaveMailer.QueueMemberLeave(ctx, workspaceID, principal.User.ID); err != nil {
			slog.ErrorContext(ctx, "queue workspace member-leave email failed", "error", err)
		}
	}
	if r.WorkspaceRoles.Publisher != nil {
		r.WorkspaceRoles.Publisher.PublishWorkspaceMembersUpdated(workspaceID)
	}
	return true, nil
}

// MentionUser is the resolver for the mentionUser field.
func (r *mutationResolver) MentionUser(ctx context.Context, input model.MentionInput) (string, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return "", ErrAuthenticationRequired
	}
	if r.Notifications == nil || r.NotificationAuth == nil {
		return "", ErrNotificationUnavailable
	}
	userID, workspaceID, doc, err := normalizeMentionInput(input)
	if err != nil {
		return "", err
	}
	if userID == principal.User.ID {
		return "", ErrMentionUserOneselfDenied
	}
	actorAccess, err := r.NotificationAuth.AuthorizeDocument(ctx, principal.User.ID, workspaceID, doc["id"].(string))
	if err != nil {
		return "", err
	}
	if !actorAccess.Update {
		return "", &MentionDocumentPermissionDeniedError{Action: "Doc.Update", WorkspaceID: workspaceID, DocID: doc["id"].(string)}
	}
	recipientAccess, err := r.NotificationAuth.AuthorizeDocument(ctx, userID, workspaceID, doc["id"].(string))
	if err != nil {
		return "", err
	}
	if !recipientAccess.Read {
		return "", &MentionUserDocAccessDeniedError{DocID: doc["id"].(string)}
	}
	id, err := r.Notifications.CreateMention(ctx, userID, workspaceID, principal.User.ID, doc)
	if err != nil {
		return "", err
	}
	r.publishNotificationCountChanged(ctx, userID, "created")
	return id, nil
}

// CreateWorkspace is the resolver for the createWorkspace field.
func (r *mutationResolver) CreateWorkspace(ctx context.Context, init *graphql.Upload) (*model.WorkspaceType, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if init != nil && init.Size > maxWorkspaceInitialDocumentBytes {
		return nil, ErrInitialWorkspaceDocumentTooLarge
	}
	workspace, err := r.WorkspaceRepo.CreateForUser(ctx, principal.User.ID)
	if err != nil {
		return nil, err
	}
	if init != nil && init.File != nil {
		content, err := io.ReadAll(io.LimitReader(init.File, maxWorkspaceInitialDocumentBytes+1))
		if err == nil {
			if int64(len(content)) > maxWorkspaceInitialDocumentBytes {
				return nil, ErrInitialWorkspaceDocumentTooLarge
			}
			if len(content) > 0 {
				if err := r.WorkspaceRepo.UpsertRootDocument(ctx, workspace.ID, principal.User.ID, content); err != nil {
					return nil, err
				}
				workspace.Initialized = true
			}
		}
	}
	return workspaceModel(workspace), nil
}

