// CreateInviteLink is the resolver for the createInviteLink field.
func (r *mutationResolver) CreateInviteLink(ctx context.Context, expireTime model.WorkspaceInviteLinkExpireTime, workspaceID string) (*model.InviteLink, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.InviteLinkCreator == nil || r.InviteLinkAuthorizer == nil {
		return nil, ErrWorkspaceInviteLinkUnavailable
	}
	allowed, err := r.InviteLinkAuthorizer.CanManageWorkspaceUsers(ctx, principal.User.ID, workspaceID)
	if err != nil {
		return nil, err
	}
	if !allowed {
		return nil, &WorkspaceMemberPermissionDeniedError{WorkspaceID: workspaceID}
	}
	link, err := r.InviteLinkCreator.Create(ctx, principal.User.ID, workspaceID, expireTime.String())
	if errors.Is(err, invitelinks.ErrPolicyDenied) {
		return nil, ErrWorkspaceInviteLinkForbidden
	}
	if errors.Is(err, invitelinks.ErrWorkspaceNameDenied) {
		return nil, ErrWorkspaceInviteLinkNameForbidden
	}
	if err != nil {
		return nil, err
	}
	if link == nil {
		return nil, fmt.Errorf("invite-link creator returned no link")
	}
	if link.Created && r.InviteLinkPublisher != nil {
		r.InviteLinkPublisher.PublishWorkspaceInviteLinkChanged(workspaceID, "invite-link-created")
	}
	return &model.InviteLink{Link: link.URL, ExpireTime: link.ExpiresAt.UTC().Format(time.RFC3339Nano)}, nil
}

// RevokeInviteLink is the resolver for the revokeInviteLink field.
func (r *mutationResolver) RevokeInviteLink(ctx context.Context, workspaceID string) (bool, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return false, ErrAuthenticationRequired
	}
	if r.InviteLinkRevoker == nil || r.InviteLinkAuthorizer == nil {
		return false, ErrWorkspaceInviteLinkUnavailable
	}
	allowed, err := r.InviteLinkAuthorizer.CanManageWorkspaceUsers(ctx, principal.User.ID, workspaceID)
	if err != nil {
		return false, err
	}
	if !allowed {
		return false, &WorkspaceMemberPermissionDeniedError{WorkspaceID: workspaceID}
	}
	deleted := r.InviteLinkRevoker.Revoke(ctx, workspaceID)
	if r.InviteLinkPublisher != nil {
		r.InviteLinkPublisher.PublishWorkspaceInviteLinkChanged(workspaceID, "invite-link-revoked")
	}
	return deleted, nil
}

