// CreateBlobUpload is the resolver for the createBlobUpload field.
func (r *mutationResolver) CreateBlobUpload(ctx context.Context, workspaceID string, key string, size int, mime string) (*model.BlobUploadInit, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.BlobUploader == nil {
		return nil, ErrBlobUploadUnavailable
	}
	init, err := r.BlobUploader.CreateBlobUpload(ctx, principal.User.ID, workspaceID, key, int64(size), mime)
	if err != nil {
		return nil, err
	}
	result := &model.BlobUploadInit{
		Method:          model.BlobUploadMethod(init.Method),
		BlobKey:         init.BlobKey,
		AlreadyUploaded: init.AlreadyUploaded,
		UploadURL:       init.UploadURL,
		ExpiresAt:       createdAt(init.ExpiresAt),
		UploadID:        init.UploadID,
	}
	if init.Headers != nil {
		result.Headers = make(model.JSONObject, len(init.Headers))
		for name, value := range init.Headers {
			result.Headers[name] = value
		}
	}
	if init.PartSize != nil {
		value := int(*init.PartSize)
		result.PartSize = &value
	}
	if init.UploadedParts != nil {
		result.UploadedParts = make([]*model.BlobUploadedPart, 0, len(init.UploadedParts))
		for _, part := range init.UploadedParts {
			result.UploadedParts = append(result.UploadedParts, &model.BlobUploadedPart{PartNumber: int(part.PartNumber), Etag: part.ETag})
		}
	}
	return result, nil
}

// CompleteBlobUpload is the resolver for the completeBlobUpload field.
func (r *mutationResolver) CompleteBlobUpload(ctx context.Context, workspaceID string, key string, uploadID *string, parts []*model.BlobUploadPartInput) (string, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return "", ErrAuthenticationRequired
	}
	if r.BlobUploader == nil {
		return "", ErrBlobUploadUnavailable
	}
	completed := make([]storage.CompletedPart, 0, len(parts))
	for _, part := range parts {
		if part == nil {
			return "", blobs.ErrBlobUploadInvalid
		}
		completed = append(completed, storage.CompletedPart{PartNumber: int32(part.PartNumber), ETag: part.Etag})
	}
	return r.BlobUploader.CompleteBlobUpload(ctx, principal.User.ID, workspaceID, key, uploadID, completed)
}

