// DeleteBlob is the resolver for the deleteBlob field.
func (r *mutationResolver) DeleteBlob(ctx context.Context, workspaceID string, hash *string, key *string, permanently bool) (bool, error) {
	if graphQLArgumentIsExplicitNull(ctx, "permanently") {
		return false, fmt.Errorf(`Argument "permanently" of non-null type "Boolean!" must not be null.`)
	}
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return false, ErrAuthenticationRequired
	}
	if r.BlobManager == nil {
		return false, ErrBlobManagementUnavailable
	}
	blobKey := ""
	if key != nil {
		blobKey = *key
	} else if hash != nil {
		blobKey = *hash
	}
	if blobKey == "" {
		return false, nil
	}
	return r.BlobManager.Delete(ctx, principal.User.ID, workspaceID, blobKey, permanently)
}

// ReleaseDeletedBlobs is the resolver for the releaseDeletedBlobs field.
func (r *mutationResolver) ReleaseDeletedBlobs(ctx context.Context, workspaceID string) (bool, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return false, ErrAuthenticationRequired
	}
	if r.BlobManager == nil {
		return false, ErrBlobManagementUnavailable
	}
	for {
		_, hasMore, err := r.BlobManager.ReleaseDeletedBatch(ctx, principal.User.ID, workspaceID, 1000)
		if err != nil {
			return false, err
		}
		if !hasMore {
			return true, nil
		}
	}
}

