// WorkspaceRolePermissions is the resolver for the workspaceRolePermissions field.
func (r *queryResolver) WorkspaceRolePermissions(ctx context.Context, id string) (*model.WorkspaceRolePermissions, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.WorkspacePermissionReader == nil {
		return nil, ErrWorkspaceRolePermissionsUnavailable
	}
	access, err := r.WorkspacePermissionReader.GetWorkspaceRolePermissions(ctx, principal.User.ID, id)
	if errors.Is(err, workspaces.ErrAccessDenied) || errors.Is(err, workspaces.ErrNotFound) {
		return nil, &WorkspacePermissionsDeniedError{WorkspaceID: id}
	}
	if err != nil {
		return nil, err
	}
	permissions, err := workspacePermissionsModel(access.Permissions)
	if err != nil {
		return nil, err
	}
	role := model.Permission(access.Role)
	switch role {
	case model.PermissionAdmin, model.PermissionCollaborator, model.PermissionExternal, model.PermissionOwner:
	default:
		return nil, fmt.Errorf("workspace authorization returned unknown role %q", access.Role)
	}
	return &model.WorkspaceRolePermissions{Role: role, Permissions: permissions}, nil
}

