func (r *serverConfigTypeResolver) AvailableUpgrade(ctx context.Context, obj *model.ServerConfigType) (*model.ReleaseVersionType, error) {
	if r.Resolver.Config.Deployment != "selfhosted" || r.Resolver.UpgradeChecker == nil {
		return nil, nil
	}
	release, err := r.Resolver.UpgradeChecker.Available(ctx, r.Resolver.Config.Namespace, r.Resolver.Config.Version)
	if err != nil {
		slog.Default().Error("failed to fetch affine releases", "error", err)
		return nil, nil
	}
	if release == nil {
		return nil, nil
	}
	return &model.ReleaseVersionType{
		Version:     release.Version,
		URL:         release.URL,
		PublishedAt: release.PublishedAt.UTC().Format("2006-01-02T15:04:05.000Z"),
		Changelog:   release.Changelog,
	}, nil
}

