// Notifications is the resolver for the notifications field.
func (r *userTypeResolver) Notifications(ctx context.Context, obj *model.UserType, pagination model.PaginationInput) (*model.PaginatedNotificationObjectType, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.Resolver.Notifications == nil {
		return nil, ErrNotificationUnavailable
	}
	first := 10
	if pagination.First != nil {
		first = *pagination.First
	}
	if first < 1 {
		first = 1
	}
	if first > 100 {
		first = 100
	}
	offset := 0
	if pagination.Offset != nil && *pagination.Offset > 0 {
		offset = *pagination.Offset
	}
	var after *time.Time
	if pagination.After != nil && *pagination.After != "" {
		if offset > 0 {
			return nil, ErrInvalidNotificationPagination
		}
		decoded, err := base64.StdEncoding.DecodeString(*pagination.After)
		if err != nil {
			return nil, ErrInvalidNotificationPagination
		}
		cursorTime, err := time.Parse(time.RFC3339Nano, string(decoded))
		if err != nil {
			return nil, ErrInvalidNotificationPagination
		}
		after = &cursorTime
	}
	total, err := r.Resolver.Notifications.CountUnread(ctx, principal.User.ID)
	if err != nil {
		return nil, err
	}
	items, err := r.Resolver.Notifications.ListUnread(ctx, principal.User.ID, after, first, offset)
	if err != nil {
		return nil, err
	}
	edges := make([]*model.NotificationObjectTypeEdge, 0, len(items))
	for _, item := range items {
		cursor := base64.StdEncoding.EncodeToString([]byte(item.CreatedAt.UTC().Format("2006-01-02T15:04:05.000Z")))
		edges = append(edges, &model.NotificationObjectTypeEdge{
			Cursor: cursor,
			Node: &model.NotificationObjectType{
				ID: item.ID, Level: model.NotificationLevel(item.Level), Type: model.NotificationType(item.Type),
				Read: item.Read, CreatedAt: item.CreatedAt.UTC().Format(time.RFC3339Nano),
				UpdatedAt: item.UpdatedAt.UTC().Format(time.RFC3339Nano), Body: model.JSONObject(item.Body),
			},
		})
	}
	var startCursor, endCursor *string
	if len(edges) > 0 {
		start, end := edges[0].Cursor, edges[len(edges)-1].Cursor
		startCursor, endCursor = &start, &end
	}
	return &model.PaginatedNotificationObjectType{
		TotalCount: total,
		Edges:      edges,
		PageInfo: &model.PageInfo{
			StartCursor: startCursor, EndCursor: endCursor,
			HasNextPage: len(edges) >= first, HasPreviousPage: after != nil || offset > 0,
		},
	}, nil
}

