// Members is the resolver for the members field.
func (r *workspaceTypeResolver) Members(ctx context.Context, obj *model.WorkspaceType, query *string, skip *int, take *int) ([]*model.InviteUserType, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.WorkspaceMembers == nil {
		return nil, ErrWorkspaceMembersUnavailable
	}
	search := ""
	if query != nil {
		search = *query
	}
	offset, limit := 0, 8
	if skip != nil {
		offset = *skip
	}
	if take != nil {
		limit = *take
	}
	items, err := r.WorkspaceMembers.ListMembersForUser(ctx, principal.User.ID, obj.ID, search, offset, limit)
	if errors.Is(err, workspaces.ErrAccessDenied) {
		return nil, &WorkspaceMemberPermissionDeniedError{WorkspaceID: obj.ID}
	}
	if errors.Is(err, workspaces.ErrMemberQueryTooLong) {
		return nil, ErrWorkspaceMemberQueryTooLong
	}
	if err != nil {
		return nil, err
	}
	result := make([]*model.InviteUserType, 0, len(items))
	for _, item := range items {
		name, email := item.Name, item.Email
		result = append(result, &model.InviteUserType{
			ID: item.ID, InviteID: item.InviteID, Name: &name, Email: &email,
			AvatarURL: item.AvatarURL, Permission: model.Permission(item.Role),
			Role: model.Permission(item.Role), Status: model.WorkspaceMemberStatus(item.Status),
		})
	}
	return result, nil
}

// InviteLink is the resolver for the inviteLink field.
func (r *workspaceTypeResolver) InviteLink(ctx context.Context, obj *model.WorkspaceType) (*model.InviteLink, error) {
	principal := auth.PrincipalFromContext(ctx)
	if principal == nil {
		return nil, ErrAuthenticationRequired
	}
	if r.InviteLinkReader == nil || r.InviteLinkAuthorizer == nil {
		return nil, ErrWorkspaceInviteLinkUnavailable
	}
	allowed, err := r.InviteLinkAuthorizer.CanManageWorkspaceUsers(ctx, principal.User.ID, obj.ID)
	if err != nil {
		return nil, err
	}
	if !allowed {
		return nil, &WorkspaceMemberPermissionDeniedError{WorkspaceID: obj.ID}
	}
	link, err := r.InviteLinkReader.Get(ctx, obj.ID)
	if err != nil || link == nil {
		return nil, err
	}
	expiresAt := link.ExpiresAt.UTC().Format(time.RFC3339Nano)
	return &model.InviteLink{Link: link.URL, ExpireTime: expiresAt}, nil
}

